                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("ALREADY_REVOKED"));
    }

    @Test
    void getUnknownCertificateReturns404() throws Exception {
        mvc.perform(get("/api/certificates/{id}", 999999))
                .andExpect(status().isNotFound());
